import os
import re
from typing import Any, Dict, List, Optional

import requests


PERSPECTIVE_API_URL = "https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze"


def _get_thresholds() -> Dict[str, float]:
    return {
        "TOXICITY": float(os.getenv("TOXICITY_THRESHOLD", "0.80")),
        "SEVERE_TOXICITY": float(os.getenv("SEVERE_TOXICITY_THRESHOLD", "0.80")),
        "INSULT": float(os.getenv("INSULT_THRESHOLD", "0.80")),
        "THREAT": float(os.getenv("THREAT_THRESHOLD", "0.80")),
        "IDENTITY_ATTACK": float(os.getenv("IDENTITY_ATTACK_THRESHOLD", "0.80")),
        "PROFANITY": float(os.getenv("PROFANITY_THRESHOLD", "0.80")),
    }


def _normalize_indices(text: str, begin: Optional[int], end: Optional[int]) -> Optional[tuple]:
    if begin is None or end is None:
        return None
    begin = max(0, min(len(text), int(begin)))
    end = max(0, min(len(text), int(end)))
    if begin >= end:
        return None
    return begin, end


def _merge_spans(spans: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    if not spans:
        return []
    spans = sorted(spans, key=lambda x: (x["start"], x["end"]))
    merged = [spans[0].copy()]
    for span in spans[1:]:
        last = merged[-1]
        if span["start"] <= last["end"]:
            last["end"] = max(last["end"], span["end"])
            last["types"] = sorted(set(last["types"]) | set(span["types"]))
            last["scores"] = {**last["scores"], **span["scores"]}
        else:
            merged.append(span.copy())
    return merged


def _redact_text(text: str, spans: List[Dict[str, Any]], placeholder: str = "[REDACTED]") -> str:
    if not spans:
        return text
    spans = _merge_spans(spans)
    out = []
    cursor = 0
    for span in spans:
        start, end = span["start"], span["end"]
        if start > cursor:
            out.append(text[cursor:start])
        out.append(placeholder)
        cursor = end
    out.append(text[cursor:])
    return "".join(out)


def _analyze_with_perspective(text: str) -> Dict[str, Any]:
    api_key = os.getenv("PERSPECTIVE_API_KEY")
    if not api_key:
        raise RuntimeError("PERSPECTIVE_API_KEY is required")

    requested_attributes = {k: {} for k in _get_thresholds().keys()}
    payload = {
        "comment": {"text": text},
        "languages": ["en"],
        "requestedAttributes": requested_attributes,
        "doNotStore": True,
    }

    resp = requests.post(
        f"{PERSPECTIVE_API_URL}?key={api_key}",
        json=payload,
        timeout=float(os.getenv("PERSPECTIVE_TIMEOUT_SECONDS", "20")),
    )
    resp.raise_for_status()
    return resp.json()


def flag_or_redact_unsafe_spans(text: str, redact: bool = True) -> Dict[str, Any]:
    """
    Analyze text using Perspective API and return flagged spans.
    If redact=True, also return a redacted_text where unsafe spans are replaced.
    """
    analysis = _analyze_with_perspective(text)
    thresholds = _get_thresholds()

    spans: List[Dict[str, Any]] = []

    attr_scores = {}
    for attr, result in analysis.get("attributeScores", {}).items():
        summary = result.get("summaryScore", {})
        attr_scores[attr] = float(summary.get("value", 0.0))

    # Perspective does not always provide exact character spans for all attributes.
    # Use span annotations when available; otherwise fall back to flagging the whole text
    # if any attribute exceeds threshold.
    annotations = analysis.get("spanAnnotations", []) or analysis.get("attributeScores", {}).get("SPAM", {}).get("spanScores", [])
    for ann in annotations:
        start_end = _normalize_indices(
            text,
            ann.get("beginOffset"),
            ann.get("endOffset"),
        )
        if not start_end:
            continue
        start, end = start_end
        scores = ann.get("scores", {})
        matched_attrs = []
        for attr, threshold in thresholds.items():
            score = float(scores.get(attr, scores.get(attr.lower(), 0.0)))
            if score >= threshold:
                matched_attrs.append(attr)
        if matched_attrs:
            spans.append(
                {
                    "start": start,
                    "end": end,
                    "types": matched_attrs,
                    "scores": {k: float(v) for k, v in scores.items() if isinstance(v, (int, float))},
                }
            )

    if not spans:
        matched_attrs = [attr for attr, score in attr_scores.items() if score >= thresholds.get(attr, 1.0)]
        if matched_attrs:
            spans = [
                {
                    "start": 0,
                    "end": len(text),
                    "types": matched_attrs,
                    "scores": attr_scores,
                }
            ]

    spans = _merge_spans(spans)
    result: Dict[str, Any] = {
        "flagged": bool(spans),
        "spans": spans,
        "provider": "Perspective API",
        "analysis": analysis,
    }
    if redact:
        result["redacted_text"] = _redact_text(text, spans)
    return result


def detect_unsafe_spans(text: str) -> List[Dict[str, Any]]:
    return flag_or_redact_unsafe_spans(text, redact=False)["spans"]


def redact_unsafe_spans(text: str, placeholder: str = "[REDACTED]") -> str:
    result = flag_or_redact_unsafe_spans(text, redact=True)
    redacted = result.get("redacted_text", text)
    if placeholder != "[REDACTED]":
        redacted = redacted.replace("[REDACTED]", placeholder)
    return redacted
